-- Idempotent install for metrics.metrics
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS metrics;

CREATE SEQUENCE IF NOT EXISTS metrics.metrics_row_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS metrics.metrics (
    row_id integer NOT NULL,
    metric_name character varying(50) NOT NULL,
    query text NOT NULL,
    metric_type character varying(50),
    metric_description text,
    category_id integer,
    entry_date timestamp without time zone DEFAULT now() NOT NULL
);

ALTER TABLE metrics.metrics ALTER COLUMN row_id SET DEFAULT nextval('metrics.metrics_row_id_seq'::regclass);
ALTER SEQUENCE metrics.metrics_row_id_seq OWNED BY metrics.metrics.row_id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE metrics.metrics);
SELECT row_id, metric_name, query, metric_type, metric_description, category_id, entry_date FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM metrics.metrics);
DROP TABLE _stg_load;

SELECT setval('metrics.metrics_row_id_seq', GREATEST((SELECT COALESCE(max(row_id),0) FROM metrics.metrics),1), (SELECT count(*) FROM metrics.metrics) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'metrics' AND c.relname = 'metrics'
          AND con.conname = 'metrics_pkey') THEN
        ALTER TABLE ONLY metrics.metrics
    ADD CONSTRAINT metrics_pkey PRIMARY KEY (row_id);
    END IF;
END $do$;
